#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
#
# One-time setup: get Stemlab's signed Windows installer into the Microsoft
# Store via the MSI/EXE submission path. See the README under Releases and
# docs/store-listing.md.
#
# Cadent went first, so the Partner Center account, the Azure Artifact
# Signing account and its certificate already exist. This wizard reuses them
# and only does what is new for Stemlab: the six signing secrets on this repo
# (copied from Cadent's .env when it is next door), a signed release on R2 to
# point at, and the Stemlab app in Partner Center. Nothing here creates an
# account or an identity validation; scripts/store_setup_wizard.sh in the
# Cadent repo is the wizard for that.
#
# Order matters: a release has to exist before the Store can be told about
# it. Stage 2 checks for one and exits cleanly with the release path if there
# is none yet; re-run the wizard once a signed release is on R2.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9

REPO_SLUG="mikeallisonJS/Stemlab"
DOWNLOADS_HOST="${DOWNLOADS_HOST:-downloads.mikeallisonjs.com}"
# Cadent's checkout, for the values the two apps share. Override with
# CADENT_ENV=/path/to/cadent/.env if it lives elsewhere.
CADENT_ENV="${CADENT_ENV:-$(dirname "$PWD")/cadent/.env}"
PARTNER_CENTER="https://partner.microsoft.com/dashboard"

# gh reads this wherever a command takes no --repo, which includes the
# library's `gh secret set`. Without it a fork checkout would receive the
# secrets while stage 1 checked for them here.
export GH_REPO="$REPO_SLUG"

AZURE_NAMES=(AZURE_SIGN_TENANT_ID AZURE_SIGN_CLIENT_ID AZURE_SIGN_CLIENT_SECRET
             AZURE_SIGN_ENDPOINT AZURE_SIGN_ACCOUNT AZURE_SIGN_PROFILE)
R2_NAMES=(R2_ACCOUNT_ID R2_ACCESS_KEY_ID R2_SECRET_ACCESS_KEY R2_BUCKET R2_PUBLIC_HOST)

# _from_file KEY FILE: KEY's value in another wizard's .env, if any.
_from_file() { (ENV_FILE="$2"; _existing "$1"); }

# _count_secrets NAME...: how many of the named repo secrets exist.
_count_secrets() {
  local have; have=$(gh secret list --repo "$REPO_SLUG" 2>/dev/null | cut -f1) || { echo 0; return; }
  local n=0 name
  for name in "$@"; do grep -qx "$name" <<<"$have" && n=$((n + 1)); done
  echo "$n"
}

banner "Stemlab — Microsoft Store setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Prerequisites — gh, and the secrets the release build needs"
GH_OK=0
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  printf '  %s✓%s gh is installed and authenticated\n' "$GREEN" "$RESET"
  GH_OK=1
else
  warn "gh is missing or not logged in: run gh auth login"
  note "Without it this stage cannot read or set the repository secrets."
  confirm "Continue anyway?" || { say "Fix the above and re-run."; exit 0; }
fi

if (( GH_OK )); then
  say ""
  say "The Store takes a signed installer from a URL that never changes. The"
  say "release build makes exactly that when two groups of secrets are set:"
  R2_COUNT=$(_count_secrets "${R2_NAMES[@]}")
  if [[ "$R2_COUNT" -eq 5 ]]; then
    printf '  %s✓%s R2_* (5/5): the build publishes to %s\n' "$GREEN" "$RESET" "$DOWNLOADS_HOST"
  else
    warn "R2_* secrets: $R2_COUNT/5. A tag build fails without all five."
    note "Set them with: gh secret set R2_ACCOUNT_ID R2_ACCESS_KEY_ID R2_SECRET_ACCESS_KEY R2_BUCKET R2_PUBLIC_HOST"
    SKIPPED+=("the five R2_* secrets on $REPO_SLUG")
  fi

  AZURE_COUNT=$(_count_secrets "${AZURE_NAMES[@]}")
  if [[ "$AZURE_COUNT" -eq 6 ]]; then
    printf '  %s✓%s AZURE_SIGN_* (6/6): Windows builds are signed\n' "$GREEN" "$RESET"
  else
    [[ "$AZURE_COUNT" -eq 0 ]] \
      && warn "AZURE_SIGN_* secrets: none. Windows builds are unsigned, and the Store rejects unsigned installers." \
      || warn "AZURE_SIGN_* secrets: $AZURE_COUNT/6. A partial set fails the build on purpose."
    say ""
    say "Signing is shared with Cadent: one Artifact Signing account and one"
    say "certificate serve both apps, so the six values are Cadent's six values."
    COPY_OK=1
    for name in "${AZURE_NAMES[@]}"; do
      [[ -n "$(_from_file "$name" "$CADENT_ENV" 2>/dev/null || true)" ]] || COPY_OK=0
    done
    if (( COPY_OK )); then
      printf '  %s✓%s found all six in %s\n' "$GREEN" "$RESET" "$CADENT_ENV"
      if confirm "Copy them to $REPO_SLUG as secrets now?"; then
        for name in "${AZURE_NAMES[@]}"; do
          value=$(_from_file "$name" "$CADENT_ENV")
          write_env "$name" "$value"
          set_secret "$name" "$value"
        done
      fi
    else
      note "Cadent's .env was not found at $CADENT_ENV (set CADENT_ENV to point at it),"
      note "so enter the six values by hand. They are what Cadent's store wizard"
      note "captured: Azure portal > the Artifact Signing account, and the"
      note "app registration that signs for CI."
      ask        AZURE_SIGN_TENANT_ID     "Entra tenant ID:"
      ask        AZURE_SIGN_CLIENT_ID     "Signing app registration, Application (client) ID:"
      ask_secret AZURE_SIGN_CLIENT_SECRET "Its client secret value:"
      ask        AZURE_SIGN_ENDPOINT      "Artifact Signing endpoint (e.g. https://eus.codesigning.azure.net):"
      ask        AZURE_SIGN_ACCOUNT       "Artifact Signing account name:"
      ask        AZURE_SIGN_PROFILE       "Certificate profile name:"
      for name in "${AZURE_NAMES[@]}"; do
        write_env "$name" "${!name}"
        set_secret "$name" "${!name}"
      done
    fi
    AZURE_COUNT=$(_count_secrets "${AZURE_NAMES[@]}")
    [[ "$AZURE_COUNT" -eq 6 ]] \
      && printf '  %s✓%s AZURE_SIGN_* (6/6) now on %s\n' "$GREEN" "$RESET" "$REPO_SLUG" \
      || warn "AZURE_SIGN_* is still $AZURE_COUNT/6. The next release will not be Store-ready."
    note "Secrets apply to builds that start after they are set. A release built"
    note "before this moment is unsigned and cannot be submitted; cut a new one."
  fi
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "A signed release on R2 — the thing the Store points at"
say "Every Store version is a URL on $DOWNLOADS_HOST that answers directly and"
say "whose bytes never change. release.yml publishes exactly that for each"
say "tag, so a release has to exist before Partner Center can be told about it."
say ""
LATEST=""
if (( GH_OK )); then
  LATEST=$(gh release list --repo "$REPO_SLUG" --limit 30 --json tagName \
    -q '[.[] | select(.tagName | test("^v[0-9]+\\.[0-9]+\\.[0-9]+$"))][0].tagName' 2>/dev/null || true)
fi
if [[ -z "$LATEST" ]]; then
  warn "no vX.Y.Z release on $REPO_SLUG yet."
  say ""
  say "Cut 1.0 first. The release flow is in the README under Releases; in short:"
  step "Merge the open PRs into v2, then open and merge a PR from v2 to main."
  step "release-pr.yml opens 'Release v1.0.0' on branch release/next. Review"
  step "  CHANGELOG.md in its diff: that is the release. Merge it."
  step "tag-release.yml tags v1.0.0 and dispatches release.yml, which builds and"
  step "  signs the installers and publishes them to R2 (about 20 minutes)."
  step "Publish the draft GitHub Release when the installers are attached."
  say ""
  note "Re-run this wizard afterwards: bash scripts/store_setup_wizard.sh"
  note "Everything captured so far is saved in $ENV_FILE."
  finish
  exit 0
fi
VERSION="${LATEST#v}"
PACKAGE_URL="https://$DOWNLOADS_HOST/stemlab/Stemlab-Setup-$VERSION.exe"
printf '  %s✓%s latest release: %s\n' "$GREEN" "$RESET" "$LATEST"
say "Checking the package URL answers 200 with no redirect (Partner Center"
say "rejects a redirect, and the GitHub Release asset URL is one):"
note "  $PACKAGE_URL"
CODE=$(curl -s -o /dev/null -w '%{http_code}' --max-redirs 0 -I "$PACKAGE_URL" || echo 000)
if [[ "$CODE" != "200" ]]; then
  warn "answered $CODE, not 200. The tag build has not published this version, or"
  warn "it failed. Check the release.yml run for $LATEST, then re-run this wizard."
  note "  gh run list --repo $REPO_SLUG --workflow release.yml"
  finish
  exit 0
fi
printf '  %s✓%s answers 200\n' "$GREEN" "$RESET"
write_env STORE_PACKAGE_URL "$PACKAGE_URL"

say ""
say "The Store also rejects an unsigned installer, and the build only signs"
say "when the secrets from stage 1 were set before it ran."
if command -v powershell.exe >/dev/null 2>&1 && confirm "Download the installer and check its signature now (~1 GB)?"; then
  TMP_EXE=$(mktemp --suffix=.exe 2>/dev/null || mktemp)
  if curl -sL --fail -o "$TMP_EXE" "$PACKAGE_URL"; then
    WIN_EXE=$(cygpath -w "$TMP_EXE" 2>/dev/null || printf '%s' "$TMP_EXE")
    SIG=$(powershell.exe -NoProfile -Command \
      "\$s = Get-AuthenticodeSignature '$WIN_EXE'; \$s.Status.ToString() + '|' + \$s.SignerCertificate.Subject" 2>/dev/null | tr -d '\r' || true)
    SIG_STATUS="${SIG%%|*}"; SIG_SUBJECT="${SIG#*|}"
    if [[ "$SIG_STATUS" == "Valid" ]]; then
      printf '  %s✓%s signed: %s\n' "$GREEN" "$RESET" "$SIG_SUBJECT"
      note "That name is what users see in the UAC and SmartScreen dialogs."
    else
      warn "signature status: ${SIG_STATUS:-unknown}. The Store will reject this installer."
      warn "Set the six AZURE_SIGN_* secrets (stage 1) and release a new version;"
      warn "a bugfix fragment is enough to bump the patch number."
      SKIPPED+=("a signed release to submit ($LATEST is unsigned)")
    fi
  else
    warn "download failed; check the signature by hand after downloading from the URL above."
  fi
  rm -f "$TMP_EXE"
else
  note "Skipped. The release.yml run for $LATEST prints 'Signed by: ...' in its"
  note "'Verify the installer's signature' step when the build was signed."
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Partner Center — the developer account"
say "The same account that owns the Cadent listing owns this one; nothing is"
say "created here. The publisher display name below is what users see under"
say "the app name in the Store, and it is the same for both apps."
if [[ -z "$(_existing MS_PUBLISHER_NAME || true)" ]]; then
  CADENT_PUBLISHER=$(_from_file MS_PUBLISHER_NAME "$CADENT_ENV" 2>/dev/null || true)
  [[ -n "$CADENT_PUBLISHER" ]] && write_env MS_PUBLISHER_NAME "$CADENT_PUBLISHER"
fi
open_url "$PARTNER_CENTER/apps-and-games/overview"
step "Sign in with the Microsoft account that owns the Cadent listing."
step "Account settings (gear) > Account settings shows the publisher display name."
ask MS_PUBLISHER_NAME "Publisher display name:"
write_env MS_PUBLISHER_NAME "$MS_PUBLISHER_NAME"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Listing assets — logos and screenshots"
say "A submission needs Store logos and at least one screenshot, and the"
say "wizard cannot make either. Check what is on disk before Partner Center"
say "asks for them."
say ""
say "Logos, built from the app icon, as PNG in docs/store/:"
note "  box-art-2160.png             2160 × 2160   1:1 box art, required for MSI/EXE"
note "  poster-art-1440x2160.png     1440 × 2160   2:3 poster art, recommended"
note "  app-tile-300.png              300 × 300    1:1 tile, recommended"
note "Keep the bottom third of the box and poster art free of anything but"
note "background: the Store may overlay text there."
ART_MISSING=0
for f in docs/store/box-art-2160.png docs/store/poster-art-1440x2160.png docs/store/app-tile-300.png; do
  if [[ -f "$f" ]]; then printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$f"; else warn "missing: $f"; ART_MISSING=1; fi
done
if (( ART_MISSING )); then
  warn "Stemlab has no app icon yet (app/src/main/README.md lists it as not done)."
  warn "The icon comes first; the three logos are renders of it."
  SKIPPED+=("Store logos in docs/store/ (needs an app icon first)")
fi
say ""
say "Screenshots: PNG, 1366 × 768 or 1920 × 1080, all the same size, up to 10."
say "The shot list and captions are in docs/store-screenshots.md."
SHOTS=$(ls docs/store/screenshot-*.png 2>/dev/null | wc -l | tr -d ' ')
if [[ "$SHOTS" -gt 0 ]]; then
  printf '  %s✓%s %s screenshot(s) in docs/store/\n' "$GREEN" "$RESET" "$SHOTS"
else
  warn "no docs/store/screenshot-*.png yet. Take them from the running app."
  SKIPPED+=("at least one Store screenshot (docs/store-screenshots.md)")
fi
note "Partner Center hosts the files; keeping copies in docs/store/ is for the"
note "next submission, not a requirement."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Partner Center — create the app"
open_url "$PARTNER_CENTER/apps-and-games/overview"
step "Apps and games > New product > MSI or EXE app."
step "Reserve the name 'Stemlab'. If it is taken, pick the closest you can live"
step "  with; the name is what people search for."
step "Product management > Product identity shows the Store ID: fourteen"
step "  characters starting with XP. Copy it."
note "It is also the last path segment of the app's Store link,"
note "apps.microsoft.com/detail/<this>. scripts/store_api_wizard.sh needs it later."
ask STORE_PRODUCT_ID "Store ID:"
if [[ ! "$STORE_PRODUCT_ID" =~ ^[Xx][Pp] ]]; then
  warn "that doesn't start with XP. MSI/EXE apps get XP... ids; check you copied the Store ID."
  confirm "Keep it anyway?" || ask STORE_PRODUCT_ID "Store ID:"
fi
write_env STORE_PRODUCT_ID "$STORE_PRODUCT_ID"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Submission — packages"
say "Start the submission and open its Packages section."
step "Package URL:"
note "    $PACKAGE_URL"
warn "That URL is version-specific and must never change. Every new version is a"
warn "NEW submission with a NEW URL; repointing an old one is against Store policy,"
warn "and the release build refuses to overwrite a published installer anyway."
step "Language: English (United States). Architecture: x64."
step "Installer parameters. The installer is NSIS, so one switch does both:"
note "    install:    /S"
note "    uninstall:  /S"
note "Silent install is the Store requirement that fails the most submissions."
note "The /S switch installs for the current user with no UI and no prompts;"
note "it is the standard NSIS switch electron-builder's installer honours."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Submission — properties, declarations, system requirements"
say "Everything on this page is written out in docs/store-listing.md under"
say "'Partner Center fields', with the reason for each choice. The short form:"
step "Category: Music."
step "Product declarations: all four boxes No. Stemlab installs no driver or"
step "  service, has not been through an accessibility audit, takes no pen"
step "  input, and separation models transform audio rather than generate it."
step "System requirements, minimum: nothing. Recommended: 16 GB memory, a"
step "  64-bit processor with 4+ cores. Leave every GPU field blank: the GPU is"
step "  optional acceleration with a CPU fallback."
step "Additional requirements: the three lines in docs/store-listing.md, which"
step "  say that first start downloads the Python runtime and that models are"
step "  downloaded on demand."
step "Age ratings: complete the questionnaire. A utility with no user content,"
step "  no social features and no ads comes out at the lowest rating."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Submission — the listing"
say "Copy is in docs/store-listing.md; the headings there are Partner Center's"
say "field names. Paste, don't retype."
step "Short description, Description and Product features from the doc."
step "Privacy policy URL:"
note "    https://github.com/$REPO_SLUG/blob/main/docs/privacy-policy.md"
step "Website: https://github.com/$REPO_SLUG"
step "Support contact: https://github.com/$REPO_SLUG/issues"
step "Logos and screenshots from stage 4, with the captions in docs/store-screenshots.md."
step "Search terms from the doc, in order; take them from the top if the field caps."
say ""
warn "Notes for certification is the field that decides whether a tester can"
warn "make the app work. Paste the draft from docs/store-listing.md and fill in"
warn "today's date: it explains the first-start download and how to run a"
warn "separation with the smallest model."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
